"use client"

import { useEffect, useRef, useState, type ReactElement } from "react"
import { Check, Copy, FileText, AudioLines, X, ChevronDown } from "lucide-react"
import { Button } from "../ui/button"
import { cn } from "cn"
import {
  Attachment,
  AttachmentContent,
  AttachmentTitle,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentAction,
} from "../ui/attachment"
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
} from "../ui/dropdown-menu"
import { avatarPixels } from "./state"
import type { ChatAttachment } from "./types"

export function AgentAvatar({
  seed = "shipbits",
  active = false,
}: {
  seed?: string
  active?: boolean
}): ReactElement {
  const pixels = avatarPixels(seed)
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 25 25"
      className="size-7 shrink-0 rounded-full data-[active=true]:animate-[sb-chat-avatar_6s_ease-in-out_infinite] motion-reduce:animate-none"
      data-active={active}
    >
      {pixels.map((pixel, index) => (
        <rect
          key={index}
          x={(index % 5) * 5}
          y={Math.floor(index / 5) * 5}
          width="5"
          height="5"
          fill={`hsl(${210 + (pixel % 100)} ${45 + (pixel % 25)}% ${32 + (pixel % 45)}%)`}
        />
      ))}
    </svg>
  )
}

export function CopyAction({
  text,
  label = "Copy",
  compact = false,
}: {
  text: string
  label?: string
  compact?: boolean
}): ReactElement {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle")
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const mounted = useRef(true)
  useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
      if (timer.current) clearTimeout(timer.current)
    }
  }, [])
  async function copy(): Promise<void> {
    try {
      await navigator.clipboard.writeText(text)
      if (!mounted.current) return
      setState("copied")
    } catch {
      if (!mounted.current) return
      setState("failed")
    }
    if (timer.current) clearTimeout(timer.current)
    timer.current = setTimeout(() => setState("idle"), 2200)
  }
  return (
    <span className="inline-flex items-center gap-1.5">
      <Button
        type="button"
        variant="ghost"
        size={compact ? "icon-xs" : "sm"}
        title={state === "copied" ? "Copied" : label}
        aria-label={state === "copied" ? "Copied" : label}
        onClick={() => void copy()}
      >
        {state === "copied" ? (
          <Check data-icon="inline-start" />
        ) : (
          <Copy data-icon="inline-start" />
        )}
        {!compact && (state === "copied" ? "Copied" : label)}
      </Button>
      <span
        role="status"
        className={state === "failed" ? "text-xs text-destructive" : "sr-only"}
      >
        {state === "failed"
          ? "Copy unavailable. Select the text to copy."
          : state === "copied"
            ? "Copied to clipboard"
            : ""}
      </span>
    </span>
  )
}

export function Choice({
  value,
  label,
  options,
  onChange,
  disabled = false,
}: {
  value: string
  label: string
  options: { id: string; label: string; description?: string }[]
  onChange: (value: string) => void
  disabled?: boolean
}): ReactElement {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        disabled={disabled}
        render={<Button variant="ghost" size="sm" />}
        aria-label={`${label}: ${options.find((item) => item.id === value)?.label ?? value}`}
      >
        {options.find((item) => item.id === value)?.label ?? value}
        <ChevronDown data-icon="inline-end" />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        side="top"
        align="start"
        className="min-w-44 motion-reduce:animate-none! motion-reduce:transition-none! motion-reduce:[&_*]:animate-none! motion-reduce:[&_*]:scroll-auto! motion-reduce:[&_*]:transition-none! motion-reduce:[&_*::before]:animate-none! motion-reduce:[&_*::before]:transition-none!"
      >
        <DropdownMenuGroup aria-label={label}>
          {options.map((option) => (
            <DropdownMenuItem
              key={option.id}
              onClick={() => onChange(option.id)}
            >
              <span className="flex flex-1 flex-col gap-0.5">
                <span>{option.label}</span>
                {option.description && (
                  <span className="text-xs text-muted-foreground">
                    {option.description}
                  </span>
                )}
              </span>
              {option.id === value && <Check aria-hidden="true" />}
            </DropdownMenuItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function AudioPreview({
  attachment,
}: {
  attachment: ChatAttachment
}): ReactElement | null {
  const audio = useRef<HTMLAudioElement>(null)
  useEffect(() => {
    if (!attachment.file || attachment.url) return
    const url = URL.createObjectURL(attachment.file)
    if (audio.current) audio.current.src = url
    return () => URL.revokeObjectURL(url)
  }, [attachment.file, attachment.url])
  return (
    <audio
      ref={audio}
      controls
      preload="metadata"
      src={attachment.url}
      aria-label={`Play ${attachment.name}`}
      className="h-8 w-full min-w-0"
    />
  )
}

export function AttachmentList({
  attachments,
  onRemove,
}: {
  attachments: ChatAttachment[]
  onRemove?: (id: string) => void
}): ReactElement {
  return (
    <div className="flex min-w-0 flex-wrap gap-2">
      {attachments.map((attachment) => (
        <Attachment
          key={attachment.id}
          size="xs"
          className="max-w-full"
          state="done"
        >
          <AttachmentMedia>
            {attachment.mediaType.startsWith("audio/") ? (
              <AudioLines aria-hidden="true" />
            ) : (
              <FileText aria-hidden="true" />
            )}
          </AttachmentMedia>
          <AttachmentContent>
            <AttachmentTitle>{attachment.name}</AttachmentTitle>
            <AttachmentDescription>
              {attachment.size < 1024 * 1024
                ? `${Math.max(1, Math.round(attachment.size / 1024))} KB`
                : `${(attachment.size / 1024 / 1024).toFixed(1)} MB`}
            </AttachmentDescription>
          </AttachmentContent>
          {onRemove && (
            <AttachmentAction
              type="button"
              aria-label={`Remove ${attachment.name}`}
              onClick={() => onRemove(attachment.id)}
            >
              <X />
            </AttachmentAction>
          )}
          {attachment.mediaType.startsWith("audio/") && (
            <div className="w-full min-w-0 px-2 pb-2">
              <AudioPreview attachment={attachment} />
            </div>
          )}
        </Attachment>
      ))}
    </div>
  )
}

export function ChatLoader({
  label = "Thinking",
  variant = "dots",
}: {
  label?: string
  variant?: "dots" | "bar" | "grid"
}): ReactElement {
  const [seconds, setSeconds] = useState(0)
  useEffect(() => {
    const began = Date.now()
    const timer = setInterval(
      () => setSeconds(Math.floor((Date.now() - began) / 1000)),
      1000
    )
    return () => clearInterval(timer)
  }, [])
  return (
    <div
      className="flex items-center gap-2 text-xs text-muted-foreground"
      aria-label={label}
    >
      <span>{label}</span>
      <span
        className={cn(
          "inline-flex items-center gap-[3px] [&_i]:block [&_i]:size-[3px] [&_i]:animate-[sb-chat-pulse_1.4s_ease-in-out_infinite] [&_i]:rounded-full [&_i]:bg-current [&_i]:motion-reduce:animate-none",
          variant === "grid" &&
            "grid grid-cols-[repeat(3,3px)] gap-0.5 [&_i]:rounded-[1px]",
          variant === "bar" &&
            "h-[3px] w-11 overflow-hidden rounded-[3px] bg-border [&_i]:h-[3px] [&_i]:w-4 [&_i]:animate-[sb-chat-sweep_1.7s_ease-in-out_infinite]"
        )}
        aria-hidden="true"
      >
        {Array.from(
          { length: variant === "grid" ? 9 : variant === "bar" ? 1 : 3 },
          (_, index) => (
            <i key={index} style={{ animationDelay: `${index * 110}ms` }} />
          )
        )}
      </span>
      <span className="tabular-nums" aria-hidden="true">
        {seconds}s
      </span>
    </div>
  )
}

"use client"

import {
  useEffect,
  useId,
  useRef,
  useState,
  type ReactElement,
  type Dispatch,
  type SetStateAction,
} from "react"
import { ArrowUp, Square, Plus, Mic, X, AudioLines } from "lucide-react"
import { Button } from "../ui/button"
import {
  InputGroup,
  InputGroupTextarea,
  InputGroupAddon,
} from "../ui/input-group"
import { AttachmentList, Choice } from "./atoms"
import { validateAttachments } from "./state"
import { useRecording } from "./use-recording"
import type { AIChatProps, ChatAttachment, ChatMode } from "./types"

export function ChatComposer({
  status,
  models = [],
  capabilities,
  maxAttachments = 5,
  maxAttachmentBytes = 10 * 1024 * 1024,
  maxRecordingSeconds = 120,
  onSubmit,
  onStop,
  toolbar,
  draft,
  onDraftChange: setDraft,
  focusRequest,
}: Pick<
  AIChatProps,
  | "status"
  | "models"
  | "capabilities"
  | "maxAttachments"
  | "maxAttachmentBytes"
  | "maxRecordingSeconds"
  | "onSubmit"
  | "onStop"
  | "toolbar"
> & {
  draft: string
  onDraftChange: Dispatch<SetStateAction<string>>
  focusRequest: number
}): ReactElement {
  const [attachments, setAttachments] = useState<ChatAttachment[]>([])
  const [modelId, setModelId] = useState(models[0]?.id ?? "")
  const [effort, setEffort] = useState(models[0]?.efforts?.[0] ?? "")
  const [mode, setMode] = useState<ChatMode>("agent")
  const [error, setError] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const input = useRef<HTMLTextAreaElement>(null)
  const files = useRef<HTMLInputElement>(null)
  const mounted = useRef(true)
  const id = useId()
  const busy = status === "submitted" || status === "streaming"
  const model = models.find((item) => item.id === modelId) ?? models[0]
  const selectedEffort = model?.efforts?.includes(effort)
    ? effort
    : (model?.efforts?.[0] ?? "")

  useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
    }
  }, [])
  useEffect(() => {
    if (focusRequest) input.current?.focus()
  }, [focusRequest])
  useEffect(() => {
    if (!input.current) return
    input.current.style.height = "auto"
    input.current.style.height = `${Math.min(input.current.scrollHeight, 216)}px`
  }, [draft])

  function addFiles(incoming: File[]): void {
    const failure = validateAttachments(
      attachments.length,
      incoming,
      maxAttachments,
      maxAttachmentBytes
    )
    if (failure) {
      setError(failure)
      return
    }
    setError("")
    const added = incoming.map((file) => ({
      id: crypto.randomUUID(),
      name: file.name,
      size: file.size,
      mediaType: file.type,
      file,
    }))
    setAttachments((current) => [...current, ...added])
  }
  const voice = useRecording((file) => addFiles([file]), maxRecordingSeconds)

  async function submit(): Promise<void> {
    if (
      busy ||
      submitting ||
      voice.recording ||
      voice.requesting ||
      (!draft.trim() && !attachments.length)
    )
      return
    setError("")
    setSubmitting(true)
    try {
      await onSubmit({
        text: draft.trim(),
        attachments,
        modelId: model?.id ?? "",
        effort: selectedEffort,
        mode,
      })
      if (mounted.current) {
        setDraft((current) => (current === draft ? "" : current))
        const sentIds = new Set(attachments.map((attachment) => attachment.id))
        setAttachments((current) =>
          current.filter((attachment) => !sentIds.has(attachment.id))
        )
        input.current?.focus()
      }
    } catch {
      if (mounted.current)
        setError("Message was not sent. Your draft is still here. Try again.")
    } finally {
      if (mounted.current) setSubmitting(false)
    }
  }

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault()
        void submit()
      }}
      className="relative rounded-[20px] bg-foreground/13 p-px before:pointer-events-none before:absolute before:-inset-px before:rounded-[inherit] before:bg-[conic-gradient(from_var(--sb-chat-angle),transparent_35%,#779bb766_46%,#9c91bc99_52%,#b5bc9e66_58%,transparent_69%)] before:opacity-0 before:transition-opacity before:duration-[400ms] before:content-[''] data-[active=true]:before:animate-[sb-chat-beam_8s_linear_infinite] data-[active=true]:before:opacity-80 before:motion-reduce:animate-none before:motion-reduce:transition-none"
      data-active={busy}
    >
      <input
        ref={files}
        type="file"
        multiple
        hidden
        aria-label="Attach files"
        onChange={(event) => {
          addFiles(Array.from(event.target.files ?? []))
          event.target.value = ""
        }}
      />
      <InputGroup className="relative h-auto rounded-[19px] border-0 bg-[color-mix(in_oklab,var(--background)_96%,var(--foreground))]! opacity-100 shadow-[0_5px_22px_#0000000a]">
        {!!attachments.length && (
          <InputGroupAddon align="block-start">
            <AttachmentList
              attachments={attachments}
              onRemove={(attachmentId) =>
                setAttachments((current) =>
                  current.filter((item) => item.id !== attachmentId)
                )
              }
            />
          </InputGroupAddon>
        )}
        <label htmlFor={id} className="sr-only">
          Message
        </label>
        <InputGroupTextarea
          ref={input}
          id={id}
          value={draft}
          placeholder="Ask something. Make something."
          rows={2}
          className="field-sizing-fixed max-h-[216px] min-h-[74px] px-4 pt-4 pb-2 text-[13px] leading-6 max-[480px]:text-base md:text-[13px]"
          aria-describedby={error || voice.error ? `${id}-error` : undefined}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (
              event.key === "Enter" &&
              !event.shiftKey &&
              !event.nativeEvent.isComposing &&
              event.keyCode !== 229
            ) {
              event.preventDefault()
              void submit()
            }
          }}
        />
        <InputGroupAddon
          align="block-end"
          className="gap-1 px-2 pt-[5px] pb-2 [&_button]:text-[11px] max-[480px]:[&_button]:px-1.5 max-[480px]:[&_button]:text-[10px]"
        >
          <div className="flex min-w-0 flex-wrap items-center gap-0.5">
            {capabilities?.mode !== false && (
              <Choice
                label="Mode"
                value={mode}
                options={[
                  { id: "agent", label: "Agent" },
                  { id: "chat", label: "Chat" },
                ]}
                onChange={(value) => setMode(value as ChatMode)}
                disabled={busy}
              />
            )}
            {!!models.length && (
              <Choice
                label="Model"
                value={model?.id ?? ""}
                options={models}
                onChange={setModelId}
                disabled={busy}
              />
            )}
            {!!model?.efforts?.length && (
              <Choice
                label="Effort"
                value={selectedEffort}
                options={model.efforts.map((item) => ({
                  id: item,
                  label: item,
                }))}
                onChange={setEffort}
                disabled={busy}
              />
            )}
            {toolbar}
          </div>
          <div className="ml-auto flex shrink-0 items-center gap-1">
            {capabilities?.attachments !== false && (
              <Button
                type="button"
                variant="ghost"
                size="icon-sm"
                title="Attach files"
                aria-label="Attach files"
                disabled={submitting}
                onClick={() => files.current?.click()}
              >
                <Plus />
              </Button>
            )}
            {capabilities?.recording !== false &&
              !voice.recording &&
              !voice.requesting && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-sm"
                  title="Record voice note"
                  aria-label="Record voice note"
                  disabled={
                    busy || submitting || attachments.length >= maxAttachments
                  }
                  onClick={() => void voice.start()}
                >
                  <Mic />
                </Button>
              )}
            {busy && onStop ? (
              <Button
                type="button"
                size="icon-sm"
                aria-label="Stop response"
                onClick={() => {
                  onStop()
                  input.current?.focus()
                }}
              >
                <Square />
              </Button>
            ) : (
              <Button
                type="submit"
                size="icon-sm"
                aria-label="Send message"
                disabled={
                  busy ||
                  submitting ||
                  voice.recording ||
                  voice.requesting ||
                  (!draft.trim() && !attachments.length)
                }
              >
                <ArrowUp />
              </Button>
            )}
          </div>
        </InputGroupAddon>
        {(voice.recording || voice.requesting) && (
          <InputGroupAddon align="block-end" className="gap-2">
            <AudioLines aria-hidden="true" />
            <span className="text-xs tabular-nums">
              {voice.requesting
                ? "Waiting for microphone…"
                : `Recording ${Math.floor(voice.seconds / 60)}:${String(voice.seconds % 60).padStart(2, "0")}`}
            </span>
            {voice.recording && (
              <Button
                type="button"
                size="sm"
                variant="secondary"
                onClick={() => voice.stop()}
              >
                Finish recording
              </Button>
            )}
            <Button
              type="button"
              variant="ghost"
              size="icon-xs"
              aria-label="Cancel recording"
              onClick={() => voice.stop(true)}
            >
              <X />
            </Button>
          </InputGroupAddon>
        )}
      </InputGroup>
      {(error || voice.error) && (
        <p
          role="alert"
          id={`${id}-error`}
          className="mt-2 text-xs text-destructive"
        >
          {error || voice.error}
        </p>
      )}
    </form>
  )
}

"use client"

import { memo, useEffect, useState, type ReactElement } from "react"
import Markdown from "react-markdown"
import remarkGfm from "remark-gfm"
import { ExternalLink, Globe, ChevronRight } from "lucide-react"
import {
  Popover,
  PopoverTrigger,
  PopoverContent,
  PopoverTitle,
  PopoverDescription,
} from "../ui/popover"
import {
  Collapsible,
  CollapsibleTrigger,
  CollapsibleContent,
} from "../ui/collapsible"
import { Button } from "../ui/button"
import { CopyAction } from "./atoms"
import type { ChatSource } from "./types"
import type { ThemedToken } from "shiki"

export const CodeBlock = memo(function CodeBlock({
  code,
  language = "text",
}: {
  code: string
  language?: string
}): ReactElement {
  const [tokens, setTokens] = useState<{
    code: string
    lines: ThemedToken[][]
  } | null>(null)
  useEffect(() => {
    let current = true
    void import("./highlight")
      .then(({ highlight }) => highlight(code, language))
      .then((lines) => {
        if (current) setTokens({ code, lines })
      })
      .catch(() => {})
    return () => {
      current = false
    }
  }, [code, language])
  return (
    <div className="overflow-hidden rounded-xl border border-border/60 bg-[#121417] text-[#d9dce2] [&_button]:text-[#9b9faa]">
      <div className="flex items-center justify-between border-b border-white/8 px-3 py-1.5 text-[10px] text-white/45">
        <span>{language}</span>
        <CopyAction text={code} compact label="Copy code block" />
      </div>
      <pre className="max-h-80 overflow-auto p-3 text-xs leading-6">
        <code>
          {tokens?.code === code
            ? tokens.lines.map((line, index) => (
                <span key={index} className="block min-h-6">
                  {line.map((token, tokenIndex) => (
                    <span key={tokenIndex} style={{ color: token.color }}>
                      {token.content}
                    </span>
                  ))}
                </span>
              ))
            : code}
        </code>
      </pre>
    </div>
  )
})

export function safeLink(url: string): string | undefined {
  try {
    const parsed = new URL(url)
    return ["https:", "http:"].includes(parsed.protocol)
      ? parsed.href
      : undefined
  } catch {
    return undefined
  }
}

function hostname(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "")
  } catch {
    return "Source"
  }
}

export function Citation({
  source,
  index,
}: {
  source: ChatSource
  index: number
}): ReactElement {
  const href = safeLink(source.url)
  return (
    <Popover>
      <PopoverTrigger
        aria-label={`Source ${index}: ${source.title}`}
        className="mx-0.5 inline-flex h-[15px] min-w-[15px] items-center justify-center rounded-[5px] border border-border bg-muted px-[3px] align-super text-[9px] leading-none text-muted-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
      >
        {index}
      </PopoverTrigger>
      <PopoverContent
        className="max-w-[calc(100vw-2rem)] motion-reduce:animate-none! motion-reduce:transition-none! motion-reduce:[&_*]:animate-none! motion-reduce:[&_*]:scroll-auto! motion-reduce:[&_*]:transition-none! motion-reduce:[&_*::before]:animate-none! motion-reduce:[&_*::before]:transition-none!"
        sideOffset={8}
      >
        <div className="flex items-center gap-2 text-[10px] text-muted-foreground">
          <Globe className="size-3" aria-hidden="true" />
          {hostname(source.url)}
        </div>
        <PopoverTitle className="mt-2 text-sm">{source.title}</PopoverTitle>
        {source.description && (
          <PopoverDescription className="mt-2 text-xs leading-relaxed">
            {source.description}
          </PopoverDescription>
        )}
        {href && (
          <a
            href={href}
            target="_blank"
            rel="noreferrer"
            className="mt-3 inline-flex items-center gap-2 rounded-sm text-xs underline underline-offset-4 focus-visible:outline-2"
          >
            Open source
            <ExternalLink className="size-3" aria-hidden="true" />
          </a>
        )}
      </PopoverContent>
    </Popover>
  )
}

export const RichText = memo(function RichText({
  text,
  sources = [],
}: {
  text: string
  sources?: ChatSource[]
}): ReactElement {
  return (
